import React, { useState, useEffect } from 'react';
import { graphql } from 'gatsby';
import PropTypes from 'prop-types';
import { Layout, Hero, About, Jobs, Education, Skills, Featured, Projects, Certifications, Contact } from '@components';
import styled from 'styled-components';
import { Main } from '@styles';
import skillOrder from '../../content/skills/robo/skillOrder.json';

const StyledMainContainer = styled(Main)`
  counter-reset: section;
`;

const RoboProfilePage = ({ location, data }) => {
  return (
    <Layout location={location}>
      <StyledMainContainer className="fillHeight">
        <Hero data={data.hero.edges} />
        <About data={data.about.edges} />
        <Jobs data={data.jobs.edges} />
        <Education data={data.education.edges} />
        <Featured data={data.featured.edges} />
        <Projects data={data.projects.edges} />
        <Skills skillsData={data.skills.edges} skillOrder={skillOrder} />
        <Certifications data={data.certifications.edges} />
        <Contact data={data.contact.edges} />
      </StyledMainContainer>
    </Layout>
  );
};

RoboProfilePage.propTypes = {
  location: PropTypes.object.isRequired,
  data: PropTypes.object.isRequired,
};

export default RoboProfilePage;


export const roboProfilePageQuery = graphql`
  {
    hero: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/hero/robo/" } }) {
      edges {
        node {
          frontmatter {
            title
            name
            subtitle
            buttonText
          }
          html
        }
      }
    }

    about: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/about/robo/" } }) {
      edges {
        node {
          frontmatter {
            title
            avatar {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
            skills
          }
          html
        }
      }
    }

    jobs: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/jobs/" }
        frontmatter: { showInExperience: { eq: true } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            title
            company
            shortname
            location
            range
            url
            tech
            logo {
              childImageSharp {
              gatsbyImageData(
                width: 700
                quality: 90
                placeholder: DOMINANT_COLOR
                layout: CONSTRAINED
              )
            }
            }
          }
          html
        }
      }
    }

    education: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/education/" }
        frontmatter: { showInEducation: { eq: true } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            school
            shortname
            programme
            score
            location
            range
            url
            logo{
              childImageSharp {
              gatsbyImageData(
                width: 700
                quality: 90
                placeholder: DOMINANT_COLOR
                layout: CONSTRAINED
              )
            }
            }
          }
          html
        }
      }
    }

    featured: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/featured/robo/" }
        frontmatter: { showInFeatured: { eq: true } }
      }
      sort: {frontmatter: {position: ASC}}
    ) {
      edges {
        node {
          frontmatter {
            title
            cover {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
            covergif
            tech
            github
            drive
            external
            youtube
            tags
          }
          html
        }
      }
    }

    projects: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/featured/robo/" }
        frontmatter: { showInProjects: { eq: true }, showInFeatured: { eq: false } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            title
            tech
            github
            external
          }
          html
        }
      }
    }

    certifications: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/certifications/robo/" }
        frontmatter: { showInCertifications: { eq: true } }
      }
      sort: {frontmatter: {priority: ASC}}
    ) {
      edges {
        node {
          frontmatter {
            course
            institute
            company
            github
            external
            tech
          }
          html
        }
      }
    }

    skills: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/skills/types/" }
        frontmatter: { showInSkills: { eq: true } }
      }
    ) {
      edges {
        node {
          frontmatter {
            name
            logo {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
          }
          html
        }
      }
    }

    contact: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/contact/" } }) {
      edges {
        node {
          frontmatter {
            title
            buttonText
          }
          html
        }
      }
    }
  }
`;